import { ChangeDetectionStrategy, Component, inject, output, signal } from '@angular/core';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { CustomerService } from '@org/api-services';
import { messageForError } from '@org/interceptors';
import { CustomerFields } from '@org/shared-models';
import { CardComponent, CloseButtonComponent } from '@org/ui';
import { CustomerFormComponent } from './customer-form';

/**
 * The form for a new customer, shown in the panel beside the list (platform U10, customer spec R2-R7). The code is generated by
 * the server (R10). It reports the created customer's id; the page opens it.
 */
@Component({
  selector: 'app-customer-add',
  standalone: true,
  imports: [TranslatePipe, CardComponent, CloseButtonComponent, CustomerFormComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="flex flex-col gap-5">
      <div class="flex items-center gap-3">
        <h1 class="mr-auto text-xl font-semibold text-primary-fg">{{ 'customer.add.title' | translate }}</h1>
        <app-close-button [label]="'customer.close' | translate" (clicked)="closed.emit()" />
      </div>
      <app-card>
        <app-customer-form [saving]="saving()" [error]="error()" submitLabel="customer.add.submit" (submitted)="add($event)" (cancelled)="closed.emit()" />
      </app-card>
    </div>
  `,
})
export class CustomerAddComponent {
  private readonly customers = inject(CustomerService);
  private readonly translate = inject(TranslateService);

  readonly created = output<string>();
  readonly closed = output<void>();

  readonly saving = signal(false);
  readonly error = signal('');

  add(fields: CustomerFields): void {
    this.saving.set(true);
    this.error.set('');
    this.customers.create(fields).subscribe({
      next: (customer) => {
        this.saving.set(false);
        this.created.emit(customer.id);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.error.set(messageForError(error, this.translate));
      },
    });
  }
}
